import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import TableSubOverview from "src/views/tables/IT-Solution-Overview/TableSubOverview";
import DialogSubOverview from "src/views/dialog/IT-Solution-Overview/DialogSubOverview";

const ITSolutionSubOverviewPage = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [subOverviewData, setSubOverviewData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");
  const { id } = useParams();
  // Testimonials
  const [overviewFormDialogOpen, setOverviewFormDialogOpen] = useState(false);
  const [overviewFormDialogMode, setOverviewFormDialogMode] = useState("add");
  const [overviewToEdit, setOverviewToEdit] = useState(null);
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [overviewToDelete, setOverviewToDelete] = useState(null);
  const location = useLocation();

  const toggleRugFormDialog = (e, mode = "add", overviewToEdit = null) => {
    setOverviewFormDialogOpen((prev) => !prev);
    setOverviewFormDialogMode(mode);
    setOverviewToEdit(overviewToEdit);
  };

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setOverviewToDelete(dataToDelete);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionSubOverview.list(id), { params })
      .then((response) => {
        console.log("SubOverviewData", response.data.data);
        setSubOverviewData(response.data.data);
        setTotalCount(response.data.data.totalCount);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.ITSolutionSubOverview.delete(overviewToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, overviewToDelete, pageSize, search]
  );
  const handleCellClick = (rowData) => {
    // navigate(`/it-solution-sublist/${itSolutionDetailsId}`);
  };
  const handleIconClick = () => {
    navigate(-1);
  };
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text={`${location.state?.title} (Overview)`} />
            </Typography>
          }
          action={
            <Button variant="contained" onClick={toggleRugFormDialog}>
              Add Sub Overview
            </Button>
          }
          backNavigation={
            <IconButton
              sx={{
                height: "30px",
                width: "30px",
                borderRadius: "50px",
                border: "2px solid #602de1c2",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
              onClick={handleIconClick}
            >
              <ArrowBackIcon sx={{ color: "#602de1c2", fontSize: "18px" }} />
            </IconButton>
          }
        />
        <Grid item xs={12}>
          <Card>
            {/* <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "All" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"All"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box> */}
            <Box sx={{ p: 5 }}>
              <TableSubOverview
                search={search}
                loading={loading}
                rows={subOverviewData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleRugFormDialog}
                onCellClick={(rowData) => handleCellClick(rowData)}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogSubOverview
        mode={overviewFormDialogMode}
        open={overviewFormDialogOpen}
        toggle={toggleRugFormDialog}
        // itSolutionOverviewId={overViewId}
        dataToEdit={overviewToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Sub Overview"
        subtitle="Are you sure you want to delete this Sub Overview?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionSubOverviewPage;
